using Godot;
using System;
using System.Globalization;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    private static void Work(Control o,string kind,long generation,Func<RefCounted,Variant> operation,bool replace=true)=>Field<Node>(o,"jobs").Call("request",kind,Callable.From(operation),generation,replace);
    public void library_selected(Control o,Settings entry){o.Set("_library_entry",entry.Duplicate(true));if(Get(entry,"kind","").AsString()=="generator"){using var synth=new AudioSynthesisOperations();o.Set("_generator_settings",Get(entry,"settings",synth.default_settings(entry["id"].AsString())).AsGodotDictionary().Duplicate(true));generate_preview(o);}refresh_inspector(o);}
    public Settings generator_payload(Settings entry,Settings settings,long seed)
    {
        string identity="";var sample=Get(settings,"sample");if(sample.VariantType==Variant.Type.String){string path=sample.AsString();identity=Godot.FileAccess.GetModifiedTime(path).ToString(CultureInfo.InvariantCulture);using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);if(file!=null)identity+=":"+file.GetLength();}string id=Get(entry,"id","").AsString();return new Settings{["id"]=id,["entry"]=entry.Duplicate(true),["label"]=Get(entry,"label","Generated sound"),["settings"]=settings.Duplicate(true),["seed"]=seed,["key"]=(id+GD.VarToStr(settings)+seed.ToString(CultureInfo.InvariantCulture)+identity).Sha256Text()};
    }
    public bool preview_matches_controls(Control o){var payload=Dict(o,"_preview_payload");if(o.Get("_preview_stream").AsGodotObject()==null||payload.Count==0||Get(Dict(o,"_library_entry"),"kind","").AsString()!="generator")return false;return Get(payload,"key","").AsString()==generator_payload(Dict(o,"_library_entry"),Dict(o,"_generator_settings"),o.Get("_generator_seed").AsInt64())["key"].AsString();}
    public void generate_preview(Control o)
    {
        var entry=Dict(o,"_library_entry");if(Get(entry,"kind","").AsString()!="generator")return;var payload=generator_payload(entry,Dict(o,"_generator_settings"),o.Get("_generator_seed").AsInt64());long generation=o.Get("_generation").AsInt64()+1;o.Set("_generation",generation);if(Dict(o,"_preview_cache").TryGetValue(payload["key"],out var cached)){set_preview(o,cached.As<AudioStreamWav>(),payload);return;}Field<Label>(o,"status").Text="Generating "+payload["label"].AsString();Work(o,"preview",generation,job=>{job.Call("update",.1,"Generating sound");using var synthesis=new AudioSynthesisOperations();var stream=synthesis.generate(payload["id"].AsString(),payload["settings"].AsGodotDictionary(),payload["seed"].AsInt64(),44100,job);return new Settings{["stream"]=stream!,["cache_key"]=payload["key"],["payload"]=payload};});
    }
    public void set_preview(Control o,AudioStreamWav? stream,Settings payload)
    {
        if(stream==null){notice(o,"The generator needs a valid source sample or its settings could not be rendered.");return;}var captured=payload.Duplicate(true);captured["stream"]=stream;o.Set("_preview_payload",captured);o.Set("_preview_stream",stream);var player=Field<AudioStreamPlayer>(o,"preview_player");player.Stream=stream;player.Play();if(payload.Count>0){var variations=Items(o,"_variations");for(int i=variations.Count-1;i>=0;i--)if(Get(variations[i].AsGodotDictionary(),"key","").AsString()==Get(payload,"key","").AsString())variations.RemoveAt(i);variations.Insert(0,captured.Duplicate(true));if(variations.Count>5)variations.Resize(5);}Field<Label>(o,"status").Text="Preview ready · "+stream.GetLength().ToString("F2",CultureInfo.InvariantCulture)+" s · "+stream.MixRate+" Hz";refresh_inspector(o);
    }
    public void add_preview(Control o){if(!preview_matches_controls(o)){Field<Label>(o,"status").Text="Wait for the preview of these exact settings before adding it.";return;}insert_generator_payload(o,Dict(o,"_preview_payload").Duplicate(true),Field<Node>(o,"playback").Get("position").AsDouble(),Session(o).Get("selected_track").AsString());}
    public void insert_generator_payload(Control o,Settings payload,double seconds,string trackId)
    {
        if(_frameLanes.is_lane(Document(o).Call("track_for_id",trackId).AsGodotDictionary())){notice(o,"Select an audio or instrument track before adding generated audio.");return;}var raw=Get(payload,"stream");if(raw.VariantType!=Variant.Type.Object||raw.AsGodotObject() is not AudioStreamWav||Get(payload,"id","").AsString().Length==0)return;var captured=payload.Duplicate(true);var session=Session(o);session.Call("begin","Add generated sound");var clip=session.Call("insert_source",captured["stream"],seconds,trackId,captured["label"].AsString()).AsGodotObject();if(clip!=null){var values=Document(o).Call("actor_for_clip",clip.Get("id")).AsGodotObject().Get("values").AsGodotDictionary();values[new StringName("generator")]=new Settings{["id"]=captured["id"],["settings"]=captured["settings"].AsGodotDictionary().Duplicate(true),["seed"]=captured["seed"]};values[new StringName("origin")]="procedural";}session.Call("commit");if(clip!=null)o.Call("fit_timeline");
    }
    public void queue_generator_drop(Control o,Settings entry,Settings settings,long seed,double seconds,string trackId)
    {
        if(_frameLanes.is_lane(Document(o).Call("track_for_id",trackId).AsGodotDictionary())){notice(o,"Choose an audio or instrument destination for generated audio.");return;}var payload=generator_payload(entry,settings,seed);Work(o,"drop_generator",Session(o).Get("revision").AsInt64(),job=>{using var synthesis=new AudioSynthesisOperations();var stream=synthesis.generate(payload["id"].AsString(),payload["settings"].AsGodotDictionary(),payload["seed"].AsInt64(),44100,job);return new Settings{["stream"]=stream!,["payload"]=payload,["track"]=trackId,["at"]=seconds};});
    }
    public void select_variation(Control o,Settings payload){var stream=Get(payload,"stream");if(stream.VariantType!=Variant.Type.Object||stream.AsGodotObject() is not AudioStreamWav wav)return;o.Set("_generation",o.Get("_generation").AsInt64()+1);Field<Node>(o,"jobs").Call("cancel_kind","preview");Field<Timer>(o,"_preview_timer").Stop();o.Set("_library_entry",payload["entry"].AsGodotDictionary().Duplicate(true));o.Set("_generator_settings",payload["settings"].AsGodotDictionary().Duplicate(true));o.Set("_generator_seed",payload["seed"].AsInt64());set_preview(o,wav,payload);}
    public Settings generator_drag_payload(Control o,Settings entry)=>Get(entry,"id","").AsString()==Get(Dict(o,"_library_entry"),"id","").AsString()&&preview_matches_controls(o)?new Settings{["audio_generator_payload"]=Dict(o,"_preview_payload").Duplicate(true)}:new Settings{["generator"]=entry.Duplicate(true),["seed"]=1};
    public void library_preview(Control o,Settings entry)
    {
        using var library=new AudioLibraryOperations();if(Get(entry,"project_indexed",false).AsBool()&&!library.valid_entry(entry)){Field<Label>(o,"status").Text="Project asset is missing, unreadable, or outside the indexed scope. Refresh its folder.";return;}switch(Get(entry,"kind","").AsString())
        {
            case "generator":library_selected(o,entry);break;
            case "instrument":using(var instruments=new AudioInstrumentOperations())o.Call("audition_note",60,instruments.default_instrument(entry["id"].AsString()));break;
            case "asset":var filePreview=Field<Node>(o,"asset_file_preview");filePreview.Call("close_file");var player=Field<AudioStreamPlayer>(o,"preview_player");player.Stop();var source=entry["source"];if(GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("needs_file_preview",source).AsBool()){if(source.AsString().GetExtension().ToLowerInvariant()=="wav"){string error=filePreview.Call("open_file",source.AsString()).AsString();if(error.Length>0)Field<Label>(o,"status").Text=error;}else Field<Label>(o,"status").Text="Add this large/compressed source to the timeline to prepare a file-backed rendered preview.";return;}var stream=o.Call("_workspace_source",source).AsGodotObject() as AudioStream;if(stream!=null){player.Stream=stream;player.Play();}break;
            case "preset":var preset=entry["preset"].AsGodotObject();if(preset.Get("kind").AsString()=="generator"){using var synth=new AudioSynthesisOperations();var data=preset.Get("data").AsGodotDictionary();var selected=synth.preset(Get(data,"id","laser").AsString());selected["kind"]="generator";o.Set("_library_entry",selected);o.Set("_generator_settings",Get(data,"settings",new Settings()).AsGodotDictionary().Duplicate(true));o.Set("_generator_seed",Get(data,"seed",1).AsInt64());generate_preview(o);refresh_inspector(o);}else o.Call("_audition_native_preset",preset);break;
        }
    }
    public void library_add(Control o,Settings entry)
    {
        using var library=new AudioLibraryOperations();if(!library.valid_entry(entry)){Field<Label>(o,"status").Text="Unsupported or invalid library entry.";return;}var session=Session(o);var playback=Field<Node>(o,"playback");switch(Get(entry,"kind","").AsString())
        {
            case "generator":if(Get(Dict(o,"_library_entry"),"id","").AsString()!=entry["id"].AsString()){library_selected(o,entry);Field<Label>(o,"status").Text="Generating the sound. Use Add to timeline when the preview is ready.";}else add_preview(o);break;
            case "instrument":session.Call("begin","Create instrument track");session.Call("add_track","instrument",entry["label"].AsString());using(var instruments=new AudioInstrumentOperations())Document(o).Call("track_for_id",session.Get("selected_track")).AsGodotDictionary()["instrument"]=instruments.default_instrument(entry["id"].AsString());o.Call("new_pattern",false);break;
            case "asset":if(_frameLanes.is_lane(Document(o).Call("track_for_id",session.Get("selected_track")).AsGodotDictionary())){notice(o,"Select an audio or instrument track before adding this asset.");return;}session.Call("insert_source",entry["source"],playback.Get("position"),session.Get("selected_track"),entry["label"].AsString());break;
            case "template":using(var templates=new AudioTemplateOperations()){var next=templates.create(entry["label"].AsString());var tabs=o.GetTree().GetFirstNodeInGroup("actor_scene_tabs");if(tabs!=null&&tabs.HasMethod("open_audio"))tabs.Call("open_audio",next);else{session.Call("open",next);o.Set("source",next);o.Set("path","");o.Set("document_path","");}}break;
            case "preset":var preset=entry["preset"].AsGodotObject();var data=preset.Get("data").AsGodotDictionary();using(var presets=new AudioPresetOperations())switch(preset.Get("kind").AsString())
            {
                case "generator":using(var synth=new AudioSynthesisOperations()){var generator=synth.preset(Get(data,"id","").AsString());generator["kind"]="generator";queue_generator_drop(o,generator,Get(data,"settings",new Settings()).AsGodotDictionary(),Get(data,"seed",1).AsInt64(),playback.Get("position").AsDouble(),session.Get("selected_track").AsString());}break;
                case "effects":if(!effect_editable(o)){notice(o,"Select an unlocked clip, audio track or master to apply effects.");return;}var owner=effect_owner(o);SessionAction(o,"Apply effect preset",()=>owner["effects"]=Get(data,"effects",new GArray()).AsGodotArray().Duplicate(true));break;
                case "instrument":var actor=session.Call("primary_actor").AsGodotObject();if(actor==null){var pattern=new KiwiAudioPreset();pattern.Set("kind","pattern");pattern.Set("label",preset.Get("label"));pattern.Set("data",new Settings{["notes"]=new GArray(),["instrument"]=data.Duplicate(true),["pattern_beats"]=4.0});string error=presets.apply_pattern(session,pattern,playback.Get("position").AsDouble(),session.Get("selected_track").AsString(),true);if(error.Length>0){notice(o,error);return;}}else{if(!session.Call("can_edit",session.Call("primary_clip").AsGodotObject().Get("id")).AsBool())return;SessionAction(o,"Apply instrument preset",()=>{var values=actor.Get("values").AsGodotDictionary();values[new StringName("instrument")]=data.Duplicate(true);values[new StringName("notes_dirty")]=true;});}o.Call("_render_dirty_notes");break;
                case "pattern":string patternError=presets.apply_pattern(session,preset,playback.Get("position").AsDouble(),session.Get("selected_track").AsString(),false);if(patternError.Length>0)notice(o,patternError);else o.Call("_render_dirty_notes");break;
                case "bundle":using(var bundles=new AudioLayerBundleOperations()){string error=bundles.insert(session,preset.Get("composition").As<RefCounted>(),playback.Get("position").AsDouble());if(error.Length>0)notice(o,error);else o.Call("_render_dirty_notes");}break;
                case "composition":var composition=preset.Get("composition").AsGodotObject();if(composition!=null){string error=composition.Call("midi_timing_error").AsString();if(error.Length>0){notice(o,error);return;}o.GetTree().GetFirstNodeInGroup("actor_scene_tabs")?.Call("open_audio",composition.Call("snapshot"));}break;
            }break;
        }
    }
    public void asset_dropped(Control o,Variant data,double seconds,string trackId)
    {
        if(_frameLanes.is_lane(Document(o).Call("track_for_id",trackId).AsGodotDictionary())){notice(o,"Drop audio or patterns onto an audio or instrument track. Automation lanes link existing parameters.");return;}if(data.VariantType==Variant.Type.Dictionary){var values=data.AsGodotDictionary();if(values.TryGetValue("audio_generator_payload",out var payload))insert_generator_payload(o,payload.AsGodotDictionary().Duplicate(true),seconds,trackId);else if(values.TryGetValue("audio_source",out var source))Session(o).Call("insert_source",source,seconds,trackId,Get(values,"label","Audio").AsString());else if(values.TryGetValue("generator",out var generator)){var entry=generator.AsGodotDictionary();using var synth=new AudioSynthesisOperations();queue_generator_drop(o,entry,Get(entry,"settings",synth.default_settings(Get(entry,"id","").AsString())).AsGodotDictionary(),Get(values,"seed",1).AsInt64(),seconds,trackId);}else if(values.TryGetValue("audio_library",out var libraryEntry)){using var library=new AudioLibraryOperations();if(!library.valid_entry(libraryEntry))return;var entry=libraryEntry.AsGodotDictionary();var preset=Get(entry,"preset");if(Get(entry,"kind","").AsString()=="preset"&&preset.VariantType==Variant.Type.Object&&preset.AsGodotObject().Get("kind").AsString()=="pattern"){using var presets=new AudioPresetOperations();string error=presets.apply_pattern(Session(o),preset.AsGodotObject(),seconds,trackId,true);if(error.Length>0)notice(o,error);else o.Call("_render_dirty_notes");}else{Session(o).Set("selected_track",trackId);Field<Node>(o,"playback").Set("position",seconds);library_add(o,entry);}}else if(values.TryGetValue("files",out var files))asset_dropped(o,files,seconds,trackId);}
        else{void File(string path){if(Array.IndexOf(new[]{"wav","mp3","ogg","flac"},path.GetExtension().ToLowerInvariant())>=0)o.Call("_queue_import",path,seconds,trackId);}if(data.VariantType==Variant.Type.PackedStringArray)foreach(string file in data.AsStringArray())File(file);else if(data.VariantType==Variant.Type.Array)foreach(var file in data.AsGodotArray())File(file.AsString());else if(data.VariantType==Variant.Type.String)File(data.AsString());}
    }
}
